const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const laGeom = ee.Geometry.Rectangle([-118.9, 33.6, -117.6, 34.4], null, false);
    const band = 'tropospheric_NO2_column_number_density';
    const qaThresh = 0.75;
    console.log(`Region: LA bbox [-118.9,33.6,-117.6,34.4]; Scale: 3000 m; QA>=${qaThresh}`);

    // Helper to evaluate EE objects
    const eeGet = (obj) => new Promise((resolve, reject) => {
      obj.evaluate((res, err) => (err ? reject(err) : resolve(res)));
    });

    function buildCollection(colId, start, end) {
      const col = ee.ImageCollection(colId)
        .filterBounds(laGeom)
        .filterDate(start, end)
        .select([band, 'qa_value'])
        .map(function (img) {
          const mask = img.select('qa_value').gte(qaThresh);
          return img.updateMask(mask);
        });
      return col;
    }

    async function getYearStats(year) {
      const start = ee.Date.fromYMD(year, 10, 1);
      const end = ee.Date.fromYMD(year, 10, 24); // end-exclusive
      let usedId = 'COPERNICUS/S5P/OFFL/L3_NO2';
      let col = buildCollection(usedId, start, end);
      let size = await eeGet(col.size());
      if (!size || size === 0) {
        usedId = 'COPERNICUS/S5P/NRTI/L3_NO2';
        col = buildCollection(usedId, start, end);
        size = await eeGet(col.size());
      }
      const img = col.select(band).mean();
      const countDict = await eeGet(img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: laGeom,
        scale: 3000,
        maxPixels: 1e9
      }));
      const meanDict = await eeGet(img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: laGeom,
        scale: 3000,
        maxPixels: 1e9
      }));
      const count = countDict ? (countDict[band] || 0) : 0;
      const mean = meanDict ? meanDict[band] : null;
      return { year, usedId, images: size || 0, validCount: count, mean };
    }

    const y2018 = await getYearStats(2018);
    const y2019 = await getYearStats(2019);
    const y2021 = await getYearStats(2021);

    // Handle C1: Empty collections for any year
    if (y2018.images === 0 || y2019.images === 0 || y2021.images === 0) {
      if (y2018.images === 0) console.log(`2018 Images: 0 (No data after OFFL->NRTI fallback)`);
      if (y2019.images === 0) console.log(`2019 Images: 0 (No data after OFFL->NRTI fallback)`);
      if (y2021.images === 0) console.log(`2021 Images: 0 (No data after OFFL->NRTI fallback)`);
      console.log('C1');
      return;
    }

    // Print image counts
    console.log(`2018 Col: ${y2018.usedId.split('/').pop()}, Images: ${y2018.images}`);
    console.log(`2019 Col: ${y2019.usedId.split('/').pop()}, Images: ${y2019.images}`);
    console.log(`2021 Col: ${y2021.usedId.split('/').pop()}, Images: ${y2021.images}`);

    // Handle C2: No valid pixels after masking
    if (y2018.validCount === 0 || y2019.validCount === 0 || y2021.validCount === 0) {
      console.log(`2018 Valid pixels: ${y2018.validCount}, 2019: ${y2019.validCount}, 2021: ${y2021.validCount}`);
      console.log('C2');
      return;
    }

    // Print valid pixels and means
    const fmt = (v) => (v === null || v === undefined ? 'null' : Number(v).toExponential(3) + ' mol/m^2');
    console.log(`2018 Valid pixels: ${y2018.validCount}, Mean NO2: ${fmt(y2018.mean)}`);
    console.log(`2019 Valid pixels: ${y2019.validCount}, Mean NO2: ${fmt(y2019.mean)}`);
    console.log(`2021 Valid pixels: ${y2021.validCount}, Mean NO2: ${fmt(y2021.mean)}`);

    // Handle C3: Calculation failure (null/NaN/unrealistic)
    const invalid = (v) => (v === null || !isFinite(v) || v < -0.001 || v > 0.01);
    if (invalid(y2018.mean) || invalid(y2019.mean) || invalid(y2021.mean)) {
      console.log('C3');
      return;
    }

    // 5. Final comparison
    const lt19 = y2021.mean < y2019.mean;
    const lt18 = y2021.mean < y2018.mean;
    console.log(`Comparisons: 2021<2019? ${lt19}; 2021<2018? ${lt18}`);
    console.log(lt19 && lt18 ? 'A' : 'B');
  } catch (e) {
    console.log(`Error: ${e && e.message ? e.message : e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
